INSERT INTO peliculas (titulo, director, anio, genero, sinopsis) VALUES
('Los Goonies', 'Richard Donner', 1985, 'Aventuras', 'Un grupo de amigos sigue un antiguo mapa para hallar un tesoro y salvar su barrio.'),
('En busca del arca perdida', 'Steven Spielberg', 1981, 'Aventuras', 'Un arqueólogo aventurero compite contra agentes enemigos para recuperar una reliquia legendaria.'),
('Indiana Jones y el templo maldito', 'Steven Spielberg', 1984, 'Aventuras', 'Indiana Jones llega a una aldea de la India y se enfrenta a un culto que oculta un poder peligroso.'),
('Indiana Jones y la última cruzada', 'Steven Spielberg', 1989, 'Aventuras', 'Indiana Jones busca a su padre desaparecido mientras ambos persiguen el Santo Grial.'),
('Regreso al futuro', 'Robert Zemeckis', 1985, 'Ciencia ficción', 'Un adolescente viaja accidentalmente al pasado y debe asegurar el futuro de su familia.'),
('Regreso al futuro II', 'Robert Zemeckis', 1989, 'Ciencia ficción', 'Marty y Doc saltan entre épocas para reparar las consecuencias de un futuro alterado.'),
('Regreso al futuro III', 'Robert Zemeckis', 1990, 'Ciencia ficción', 'Marty viaja al lejano Oeste para rescatar a Doc y encontrar una forma de regresar a su tiempo.'),
('Star Wars: Una nueva esperanza', 'George Lucas', 1977, 'Ciencia ficción', 'Un joven granjero se une a una rebelión para rescatar a una princesa y enfrentarse al Imperio.'),
('Star Wars: El Imperio contraataca', 'Irvin Kershner', 1980, 'Ciencia ficción', 'La rebelión resiste el avance imperial mientras Luke continúa su aprendizaje como Jedi.'),
('Star Wars: El retorno del Jedi', 'Richard Marquand', 1983, 'Ciencia ficción', 'Los rebeldes preparan su ataque definitivo mientras Luke intenta rescatar a su padre.'),
('Willow', 'Ron Howard', 1988, 'Fantasía', 'Un aprendiz de hechicero protege a una niña destinada a desafiar a una reina tiránica.'),
('La historia interminable', 'Wolfgang Petersen', 1984, 'Fantasía', 'Un niño descubre que el libro que lee lo conecta con un reino amenazado por la Nada.');
